package basic;

public class ForDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		
		for( int i=1 ; i<=10 ; i++)
		
		{
			System.out.println(i);
			
		}
			
		System.out.println("*****");
		
		for(int i=10; i>=1; i--)
		{
			
			if(i==5)
			{
				break;
			//continue;
			
			}
			System.out.println(i);	
		
		}
			

}
}
